old="window.addEventListener('reborn-context-lost',()=>{if(state==='play')pause();notify('GRAPHICS INTERRUPTED / DRIVE PAUSED',10);});\nwindow.addEventListener('reborn-context-restored',()=>notify('GRAPHICS RESTORED / RESUME WHEN READY',5));\nwindow.addEventListener('reborn-context-failed',()=>{$('fatal-message').textContent='Graphics recovery failed. Reload to retry.';$('fatal').hidden=false;});"
new="function graphicsBackup(){try{return releaseSessionBackup();}catch(_e){return null;}}\nfunction graphicsFailure(message){ input.clear();if(state==='play')pause();else if(state==='replay')pauseMemoryReplay();persist(); $('fatal-message').textContent=message||'Graphics recovery failed. Export this session before reloading if you need a recovery copy.';$('fatal').hidden=false; let actions=$('graphics-recovery-actions');if(!actions){actions=document.createElement('div');actions.id='graphics-recovery-actions';actions.className='session-save-actions';const exportButton=document.createElement('button');exportButton.type='button';exportButton.className='secondary';exportButton.textContent='EXPORT CURRENT SESSION';exportButton.addEventListener('click',()=>{const backup=graphicsBackup();if(backup)releaseDownload(backup,'REBORN-graphics-recovery.json');});const reloadButton=document.createElement('button');reloadButton.type='button';reloadButton.className='primary';reloadButton.textContent='RELOAD GAME';reloadButton.addEventListener('click',()=>location.reload());actions.append(exportButton,reloadButton);$('fatal-message').after(actions);} actions.hidden=false; }\nwindow.addEventListener('reborn-context-lost',()=>{ const replayPlaying=state==='replay'&&memoryReplay&&!memoryReplay.paused&&!memoryReplay.finished;graphicsInterruption={state,replayPlaying,at:performance.now()};input.clear(); if(state==='play')pause();else if(state==='replay')pauseMemoryReplay();persist();notify('GRAPHICS INTERRUPTED / SESSION PAUSED SAFELY',10); });\nwindow.addEventListener('reborn-context-restored',()=>{cameraEye=null;cameraTarget=null;accumulator=0;lastFrame=0;const previous=graphicsInterruption;graphicsInterruption=null;if(previous){$('graphics-recovery-actions')?.setAttribute('hidden','');$('fatal').hidden=true;notify(previous.state==='replay'&&previous.replayPlaying?'GRAPHICS RESTORED / REPLAY PAUSED · PRESS PLAY':'GRAPHICS RESTORED / RESUME WHEN READY',6);}});\nwindow.addEventListener('reborn-context-failed',e=>graphicsFailure('Graphics recovery failed'+(e.detail?.message?': '+e.detail.message:'')+'. Export this session before reloading if needed.'));"
rep("index.html",old,new)
